 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    positions = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            counts[color] = counts.get(color, 0) + 1
            positions.setdefault(color, []).append((r, c))
    background = max(counts, key=counts.get)

    # A diagonal pair marks a ray.  Among incidental diagonal pairs, the
    # intended ray is the one with the longest unobstructed background run.
    candidates = []
    for color, pts in positions.items():
        if color == background:
            continue
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if r1 == r2 or abs(r2-r1) != abs(c2-c1):
                    continue
                if r1 < r2:
                    end_r, end_c = r2, c2
                    dc = 1 if c2 > c1 else -1
                else:
                    end_r, end_c = r1, c1
                    dc = 1 if c1 > c2 else -1
                r, c = end_r + 1, end_c + dc
                clear = 0
                while 0 <= r < h and 0 <= c < w and grid[r][c] == background:
                    clear += 1
                    r += 1
                    c += dc
                candidates.append((clear, color, end_r, end_c, dc))
    if not candidates:
        return out
    # Stable ordering breaks ties by first-seen color/pair in the grid.
    _, color, r, c, dc = max(candidates, key=lambda x: x[0])
    r += 1
    c += dc
    while 0 <= r < h and 0 <= c < w:
        out[r][c] = color
        r += 1
        c += dc
    return out
