            counts[color] = counts.get(color, 0) + 1
            points.setdefault(color, []).append((r, c))
    background = max(counts, key=counts.get)

    # For each adjacent diagonal pair, extend the line from whichever endpoint
    # has the longer unobstructed continuation. Other colored cells stop a ray.
    for color, pts in points.items():
        if color == background:
            continue
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                if abs(r2 - r1) != 1 or abs(c2 - c1) != 1:
                    continue
                if r1 < r2:
                    upper, lower = (r1, c1), (r2, c2)
                else:
                    upper, lower = (r2, c2), (r1, c1)
                dc = 1 if lower[1] > upper[1] else -1
                # The two outward directions are up from upper and down from lower.
                directions = [
                    (upper[0] - 1, upper[1] - dc, -1, -dc),
                    (lower[0] + 1, lower[1] + dc, 1, dc),
                ]
                lengths = []
                for r, c, dr, step_c in directions:
                    n = 0
                    while 0 <= r < h and 0 <= c < w and grid[r][c] == background:
                        n += 1
                        r += dr
                        c += step_c
                    lengths.append(n)
                chosen = 0 if lengths[0] > lengths[1] else 1
                r, c, dr, step_c = directions[chosen]
                while 0 <= r < h and 0 <= c < w and grid[r][c] == background:
                    out[r][c] = color
