                a_c = c + 1 if dc == 1 else c
                b_c = c if dc == 1 else c + 1
                if grid[r2][c2] != color or color == background:
                    continue
                if grid[r][b_c] != background or grid[r2][a_c] != background:
                    continue

                # The pair is (r, a_c) then (r+1, b_c), with unit row step.
                step_c = b_c - a_c
                rays = [
                    (r - 1, a_c - step_c, -1, -step_c),
                    (r + 2, b_c + step_c, 1, step_c),
