            counts[color] = counts.get(color, 0) + 1
            positions.setdefault(color, []).append((r, c))
    background = max(counts, key=counts.get)

    # Single-cell markers extend diagonally in the direction of a nearby
    # same-colored diagonal arrangement; otherwise diagonal pairs extend.
    for color, pts in positions.items():
        if color == background:
            continue
        if len(pts) == 1:
            r, c = pts[0]
            # Extend a singleton up-right when it lies on a diagonal with
            # another object's cells above it; paint the line to the edge.
            if r > 0 and c + 1 < w and grid[r-1][c+1] != background:
                dr, dc = -1, 1
                rr, cc = r - 1, c + 1
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
        else:
            for i, (r1, c1) in enumerate(pts):
                for r2, c2 in pts[i + 1:]:
                    if abs(r2-r1) != 1 or abs(c2-c1) != 1:
                        continue
                    dr = 1 if r2 > r1 else -1
                    dc = 1 if c2 > c1 else -1
                    r, c = (r2+dr, c2+dc) if r2 > r1 else (r1+dr, c1+dc)
